gyw(){return"\u0647\u0630\u0627 \u064a\u0642\u0633\u0645 \u0627\u0644\u0639\u062f\u062f\u064a\u0646\u060c \u0644\u0643\u0646 \u0639\u062f\u062f\u064b\u0627 \u0623\u0643\u0628\u0631 \u064a\u0642\u0633\u0645\u0647\u0645\u0627 \u0623\u064a\u0636\u064b\u0627: \u0627\u0628\u062d\u062b \u0639\u0646 \u0627\u0644\u0623\u0643\u0628\u0631."},
gyx(){return"\u0627\u0644\u0639\u062f\u062f\u0627\u0646 \u064a\u0642\u0633\u0645\u0627\u0646\u0647\u060c \u0644\u0643\u0646\u0647\u0645\u0627 \u064a\u0642\u0633\u0645\u0627\u0646 \u0639\u062f\u062f\u064b\u0627 \u0623\u0635\u063a\u0631 \u0623\u064a\u0636\u064b\u0627: \u0627\u0628\u062d\u062b \u0639\u0646 \u0627\u0644\u0623\u0635\u063a\u0631."},
gyn(){return"\u0627\u0644\u0642\u0627\u0633\u0645 \u0627\u0644\u0645\u0634\u062a\u0631\u0643 \u0627\u0644\u0623\u0643\u0628\u0631 \u0644\u0627 \u064a\u0632\u064a\u062f \u0639\u0644\u0649 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0623\u0635\u063a\u0631\u061b \u0648\u0627\u0644\u0645\u0636\u0627\u0639\u0641 \u0627\u0644\u0645\u0634\u062a\u0631\u0643 \u0627\u0644\u0623\u0635\u063a\u0631 \u0644\u0627 \u064a\u0642\u0644 \u0639\u0646 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0623\u0643\u0628\u0631."},
gyP(){return"\u0636\u0631\u0628 \u0627\u0644\u0639\u062f\u062f\u064a\u0646 \u064a\u0639\u0637\u064a \u0645\u0636\u0627\u0639\u0641\u064b\u0627 \u0645\u0634\u062a\u0631\u0643\u064b\u0627\u060c \u0644\u0643\u0646 \u0644\u064a\u0633 \u062f\u0627\u0626\u0645\u064b\u0627 \u0627\u0644\u0623\u0635\u063a\u0631: \u0627\u0642\u0633\u0645\u0647 \u0639\u0644\u0649 \u0642\u0627\u0633\u0645\u0647\u0645\u0627 \u0627\u0644\u0645\u0634\u062a\u0631\u0643 \u0627\u0644\u0623\u0643\u0628\u0631."},
gyQ(){return"\u0647\u0630\u0627 \u0639\u062f\u062f \u0627\u0644\u0645\u0631\u0627\u062a \u0627\u0644\u062a\u064a \u064a\u062f\u062e\u0644 \u0641\u064a\u0647\u0627\u061b \u0627\u0644\u0628\u0627\u0642\u064a \u0647\u0648 \u0645\u0627 \u064a\u062a\u0628\u0642\u0649 \u0628\u0639\u062f \u0630\u0644\u0643."},
gyy(){return"\u0647\u0630\u0627 \u0627\u0644\u0639\u062f\u062f \u064a\u0642\u0628\u0644 \u0627\u0644\u0642\u0633\u0645\u0629 \u0639\u0644\u0649 \u0623\u0643\u062b\u0631 \u0645\u0646 1 \u0648\u0646\u0641\u0633\u0647: \u062c\u0631\u0651\u0628 \u0627\u0644\u0623\u0639\u062f\u0627\u062f \u0627\u0644\u0623\u0648\u0644\u064a\u0629 \u062d\u062a\u0649 \u062c\u0630\u0631\u0647 \u0627\u0644\u062a\u0631\u0628\u064a\u0639\u064a (2\u060c 3\u060c 5\u060c 7\u060c 11\u060c 13\u060c 17\u2026)."},
gyv(){return"\u0627\u0633\u062a\u0639\u0645\u0644 \u0627\u0644\u0642\u0648\u0627\u0639\u062f: \u0644\u0640 3 \u0623\u0648 9\u060c \u0627\u062c\u0645\u0639 \u0627\u0644\u0623\u0631\u0642\u0627\u0645\u061b \u0644\u0640 4\u060c \u0627\u0646\u0638\u0631 \u0625\u0644\u0649 \u0622\u062e\u0631 \u0631\u0642\u0645\u064a\u0646\u061b \u0644\u0640 6\u060c \u0632\u0648\u062c\u064a \u0648\u064a\u0642\u0628\u0644 \u0627\u0644\u0642\u0633\u0645\u0629 \u0639\u0644\u0649 3."},
gy7(){return"\u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0630\u064a \u0623\u0645\u0627\u0645 \u0627\u0644\u0642\u0648\u0633\u064a\u0646 \u064a\u0636\u0631\u0628 \u0643\u0644 \u0645\u0627 \u0628\u062f\u0627\u062e\u0644\u0647\u0645\u0627: 3(x + 2) \u0647\u0648 3x + 6\u060c \u0648\u0644\u064a\u0633 3x + 2."},
