gnM(){return"\u09a8\u09a4\u09c1\u09a8 \u0996\u09c7\u09b2\u09cb\u09af\u09bc\u09be\u09a1\u09bc \u09b9\u09bf\u09b8\u09c7\u09ac\u09c7 \u0986\u09ac\u09be\u09b0 \u09b6\u09c1\u09b0\u09c1 \u0995\u09b0\u09cb, \u09ac\u09be \u09ab\u09cb\u09a8\u099f\u09be \u0985\u09a8\u09cd\u09af \u0995\u09be\u0989\u0995\u09c7 \u09a6\u09be\u0993\u0964 \u09a4\u09cb\u09ae\u09be\u09b0 \u09b8\u09c7\u099f\u09bf\u0982\u09b8 \u09a5\u09c7\u0995\u09c7 \u09af\u09be\u09ac\u09c7\u0964"},
gnN(){return"\u0986\u09ac\u09be\u09b0 \u09b6\u09c1\u09b0\u09c1 \u0995\u09b0\u09ac\u09c7?"},
gnK(){return"\u09a4\u09cb\u09ae\u09be\u09b0 \u09b0\u200d\u09cd\u09af\u09be\u0999\u09cd\u0995, \u09b0\u09a4\u09cd\u09a8, \u09a4\u09be\u09b0\u09be, \u0995\u09c7\u09a8\u09be\u0995\u09be\u099f\u09be, \u0995\u09c3\u09a4\u09bf\u09a4\u09cd\u09ac \u0986\u09b0 \u09aa\u09b0\u09bf\u09b8\u0982\u0996\u09cd\u09af\u09be\u09a8 \u098f\u0987 \u09a1\u09bf\u09ad\u09be\u0987\u09b8 \u09a5\u09c7\u0995\u09c7 \u09ae\u09c1\u099b\u09c7 \u09af\u09be\u09ac\u09c7\u0964 \u098f\u099f\u09be \u0986\u09b0 \u09ab\u09c7\u09b0\u09be\u09a8\u09cb \u09af\u09be\u09ac\u09c7 \u09a8\u09be\u0964"},
gjh(){return"\u09ac\u09be\u09a4\u09bf\u09b2"},
gnL(){return"\u09b8\u09ac \u09ae\u09c1\u099b\u09c7 \u09a6\u09be\u0993"},
gDJ(){return"\u09ac\u09be\u09a6 \u09a6\u09be\u0993"},
gDH(){return"\u09aa\u09b0\u09c7"},
gDC(){return"\u0985\u09cd\u09af\u09be\u09b0\u09c7\u09a8\u09be\u09af\u09bc \u09b8\u09cd\u09ac\u09be\u0997\u09a4\u09ae"},
