gDa(){return"\u041e\u0434\u043d\u0430\u043a\u043e\u0432\u0456 \u0437\u043d\u0430\u043a\u0438: \u0434\u043e\u0434\u0430\u0432\u0430\u0439 \u0456 \u0437\u0430\u043b\u0438\u0448\u0430\u0439 \u0437\u043d\u0430\u043a. \u0420\u0456\u0437\u043d\u0456 \u0437\u043d\u0430\u043a\u0438: \u0432\u0456\u0434\u043d\u0456\u043c\u0430\u0439 \u043c\u043e\u0434\u0443\u043b\u0456 \u0439 \u0431\u0435\u0440\u0438 \u0437\u043d\u0430\u043a \u0431\u0456\u043b\u044c\u0448\u043e\u0433\u043e. \u0414\u0432\u0430 \u043c\u0456\u043d\u0443\u0441\u0438 \u043f\u043e\u0441\u043f\u0456\u043b\u044c \u0434\u0430\u044e\u0442\u044c \u043f\u043b\u044e\u0441."},
